import{z as o,x as l,o as e,c as d,q as B,j as n,D as E,d as A,s,S as i,b as t}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"可用安全","description":"","frontmatter":{"title":"可用安全","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/usable-security.md","filePath":"cs/usable-security.md","lastUpdated":1791063341000}'),p={name:"cs/usable-security.md"};function h(c,a,u,D,m,C){const r=l("Mermaid");return e(),d("div",null,[a[2]||(a[2]=B('<h1 id="可用安全" tabindex="-1">可用安全 <a class="header-anchor" href="#可用安全" aria-label="Permalink to &quot;可用安全&quot;">​</a></h1><div class="epigraph"><p>用户会绕过使他们无法完成工作的控制。Whitten 与 Tygar 表明：密码学 UI 失败则密钥管理失败。安全必须是默认且可完成的任务，而不是考试。</p><footer>—— Whitten and Tygar, Why Johnny Can&#39;t Encrypt, USENIX Security 1999；对照 Anderson 对操作</footer></div><p>上一课<a href="/cs/security-economics">安全经济学</a>讲组织激励；缺口下沉到<strong>个人操作</strong>：警告疲劳、证书对话框、MFA 摩擦。本课可用安全。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>浏览器把证书错误做成带「继续前往」按钮的对话框，用户就会点它——PKI 链验证的全部机制在一声「继续」里作废。缺口是三件设计：默认路径必须安全（安全选项是零努力选项）、失败要用人话讲清（谁、对什么、有何后果）、警告总量要砍——每条新警告都在稀释其余警告的分量。</p><h3 id="钓鱼" tabindex="-1">钓鱼 <a class="header-anchor" href="#钓鱼" aria-label="Permalink to &quot;钓鱼&quot;">​</a></h3><p>可用不等于无钓鱼：把界面做好并不能替用户识别伪造站点。WebAuthn 把凭据绑在 origin 上——假站拿不到真站的签名，这是用设计封死攻击面，不是再教育用户盯着 URL。</p><p><span class="marginnote">Johnny 1999。风险量化下一课试图给决策数字。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>方法从警告疲劳入手：用户对安全弹窗形成「全点确认」的习惯后，警告退化成仪式。设计原则相反——安全做成默认（自动更新、默认加密），把「问用户」压到最少，且只在真正分叉处问，每个问题都要给用户用得上的判断依据。下一课风险量化。</p>',11)),(e(),n(i,null,{default:E(()=>[s(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20TASK%5B%22%E7%94%A8%E6%88%B7%E8%A6%81%E5%AE%8C%E6%88%90%E7%9A%84%E5%B7%A5%E4%BD%9C%22%5D%20--%3E%20CTRL%5B%22%E6%8E%A7%E5%88%B6%22%5D%0A%20%20CTRL%20--%3E%20BYPASS%5B%22%E8%BF%87%E9%9A%BE%E5%88%99%E7%BB%95%E8%BF%87%22%5D%0A%20%20DEF%5B%22%E5%AE%89%E5%85%A8%E9%BB%98%E8%AE%A4%22%5D%20--%3E%20DONE%5B%22%E4%BB%8D%E8%83%BD%E5%AE%8C%E6%88%90%E4%BB%BB%E5%8A%A1%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[A(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("h2",{id:"机制",tabindex:"-1"},[A("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=t("p",null,"警告疲劳是一个系统自己训练出来的循环；对照的是把分叉提前吃掉的设计路线：",-1)),(e(),n(i,null,{default:E(()=>[s(r,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20WARN%5B%22%E7%B3%BB%E7%BB%9F%E5%BC%B9%E5%AE%89%E5%85%A8%E8%AD%A6%E5%91%8A%22%5D%20--%3E%20CLICK%5B%22%E7%94%A8%E6%88%B7%E7%82%B9%E7%A1%AE%E8%AE%A4%E6%89%8D%E8%83%BD%E7%BB%A7%E7%BB%AD%22%5D%0A%20%20CLICK%20--%3E%20HABIT%5B%22%E9%87%8D%E5%A4%8D%20N%20%E6%AC%A1%E5%90%8E%E5%85%BB%E6%88%90%5C%22%E8%A7%81%E5%BC%B9%E7%AA%97%E5%B0%B1%E7%A1%AE%E8%AE%A4%5C%22%22%5D%0A%20%20HABIT%20--%3E%20DULL%5B%22%E8%AD%A6%E5%91%8A%E5%A4%B1%E5%8E%BB%E4%BF%A1%E6%81%AF%E9%87%8F%22%5D%0A%20%20DULL%20--%3E%20ATTACK%5B%22%E7%9C%9F%E6%94%BB%E5%87%BB%E6%97%B6%E7%94%A8%E6%88%B7%E7%85%A7%E6%A0%B7%E7%82%B9%22%5D%0A%20%20DEF%5B%22%E8%AE%BE%E8%AE%A1%E8%B7%AF%E7%BA%BF%3A%20%E5%AE%89%E5%85%A8%E8%AE%BE%E4%B8%BA%E9%BB%98%E8%AE%A4%22%5D%20--%3E%20NOASK%5B%22%E4%BB%BB%E5%8A%A1%E7%85%A7%E5%B8%B8%E5%AE%8C%E6%88%90%2C%20%E4%B8%8D%E5%BC%B9%E7%AA%97%22%5D%0A%20%20NOASK%20--%3E%20RARE%5B%22%E5%8F%AA%E5%89%A9%E7%9C%9F%E5%88%86%E5%8F%89%E6%89%8D%E6%8F%90%E9%97%AE%22%5D%0A%20%20RARE%20--%3E%20READ%5B%22%E7%94%A8%E6%88%B7%E4%BC%9A%E8%AE%A4%E7%9C%9F%E8%AF%BB%E8%BF%99%E4%B8%80%E6%AC%A1%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[A(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=B('<p>机制上人是系统的一部分：MFA 摩擦太大，用户把一次性码转发进聊天群「保存」，控制自己制造了新漏洞；Whitten–Tygar 的实验里多数受试者用 PGP 类工具发不出加密邮件——密钥管理的 UI 失败即密钥管理失败。可用性不是体验附属，是控制生效的条件。量化下一课给管理层优先级，仍要可用。</p><p><span class="marginnote">直觉类比：走廊里的火警铃常年误报，半年后没人再抬头——不是因为员工懒，而是铃声本身已经不再携带信息。每一条 unnecessary 的安全弹窗都在给其它弹窗「扣分」：警告的预算是注意力，不是对话框数量。</span></p><p><span class="marginnote">WebAuthn 的 origin 绑定可以翻译成「凭据上刻了门牌号」：注册时凭据只认 <code>bank.example</code> 这一个域名，钓鱼站的域名不同，签名请求根本发不出去。这是用协议封死路径，而不是再指望用户盯着地址栏比对手高明。</span></p><p><span class="marginnote">常见误区：把失败归给「用户素质低、多培训就好」。Whitten–Tygar 1999 年的实验里，受训过的受试者多数仍用 PGP 类工具发不出加密邮件——培训的边际收益远低于把安全改成默认选项。设计错了，人就会错；先改设计，再谈教育。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不嘲笑用户：失败的是设计不是人——警告疲劳正是系统自己训练出来的行为。风险量化下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>激励之后，个人会绕过难用的控制。</li><li>Johnny：加密 UI 失败即密钥失败。</li><li>安全默认优于更多对话框。</li><li>下一课风险量化。</li><li>出处：Whitten and Tygar, 1999；Anderson。</li></ul>',8))])}const b=o(p,[["render",h]]);export{_ as __pageData,b as default};
